    private static readonly Dictionary<string,(string Ru,string Uk,string En)> HelpText = new(StringComparer.Ordinal)
    {
        ["Display"]=("Определяет способ обработки значения при компоновке. «Текст» — обычная строка; «Секрет» — чувствительное значение; «Коды восстановления» — отдельные коды с колонками и квадратами; BitLocker, TOTP/HOTP и многострочный текст имеют специальные правила. Исходное поле KeePassXC не меняется.",
            "Визначає спосіб обробки значення під час компонування. «Текст» — звичайний рядок; «Секрет» — чутливе значення; «Коди відновлення» — окремі коди зі стовпцями та квадратиками; BitLocker, TOTP/HOTP і багаторядковий текст мають спеціальні правила. Поле KeePassXC не змінюється.",
            "Selects how the card layout treats this value. Text is a normal line; Secret is a sensitive value; Recovery codes get separate cells, columns and checkboxes. BitLocker, TOTP/HOTP and multiline text use specialized layout. The KeePassXC field is unchanged."),
        ["GroupTitle"]=("Раздел, в котором будет размещено поле: «Основное», «Доступ», «Восстановление» или «Дополнительно». Сначала поля сортируются по разделу, затем — по приоритету внутри раздела. Заголовки разделов и линии включаются отдельно в «Оформлении».",
            "Розділ, у якому буде розташоване поле: «Основне», «Доступ», «Відновлення» чи «Додатково». Спочатку поля впорядковуються за розділом, потім — за пріоритетом усередині нього. Заголовки й лінії розділів вмикаються окремо в «Оформленні».",
            "Choose the card section: Account, Authentication, Recovery or Extra. Fields are ordered by section first and then by priority within each section. Section headings and divider lines are controlled separately in Appearance."),
        ["Label"]=("Подпись этого поля на карточке — текст над значением или слева от него, в зависимости от настроек оформления. Можно задать любое понятное имя. Это не переименовывает поле в базе KeePassXC. Если «Заголовок поля» выключен, подпись не выводится.",
            "Підпис цього поля на картці — текст над значенням або ліворуч від нього, залежно від оформлення. Можна задати будь-яку зрозумілу назву. Це не перейменовує поле в базі KeePassXC. Якщо «Заголовок поля» вимкнено, підпис не друкується.",
            "Caption printed above or to the left of the value, depending on Appearance settings. You can use any descriptive caption; this does not rename the KeePassXC field. When Field heading is off, the caption is omitted."),
        ["Priority"]=("Порядок поля внутри выбранного раздела: меньшее число печатается раньше, большее — позже. Допустимый диапазон: −9999…9999. При одинаковом приоритете сохраняется исходный порядок полей. Между разными разделами приоритет не сравнивается.",
            "Порядок поля в обраному розділі: менше число друкується раніше, більше — пізніше. Діапазон: −9999…9999. За однакового пріоритету зберігається початковий порядок полів. Між різними розділами пріоритет не порівнюється.",
            "Ordering within the selected section: lower numbers print earlier, higher numbers later. Range: −9999 to 9999. Ties preserve the original field order. Priority does not reorder fields across different sections."),
        ["Visible"]=("Управляет появлением поля на карточке. «Если заполнено» — только непустые значения; «Всегда» — даже пустое; «Не печатать» — полностью скрыть. Настройка не удаляет поле из KeePassXC и не меняет саму базу.",
            "Керує появою поля на картці. «Якщо заповнено» — лише непорожні значення; «Завжди» — навіть порожнє; «Не друкувати» — повністю приховати. Налаштування не видаляє поле з KeePassXC і не змінює базу.",
            "Controls whether a field appears on the card. When nonempty prints only filled values; Always includes empty values; Hidden omits the field. No KeePassXC data is deleted or modified."),
        ["ShowHeading"]=("Печатать ли подпись перед значением данного поля. При включении используется заданная «Подпись», расположенная сверху или слева по общим настройкам. При выключении остаётся только значение; заголовок карточки и названия разделов не затрагиваются.",
            "Чи друкувати підпис перед значенням цього поля. Якщо ввімкнено, використовується «Підпис», розташований зверху або ліворуч відповідно до загального оформлення. Якщо вимкнено — лише значення; назва картки та заголовки розділів не змінюються.",
            "Whether to print this field’s caption. When on, the configured Caption appears above or to the left of the value according to Appearance. When off, only the value is printed. The card title and section headings are unaffected."),
        ["Url"]=("Форма отображения адреса, если значение является URL. «Полный адрес» сохраняет протокол и путь; «Только домен» оставляет имя хоста; «Умный домен» дополнительно убирает известные служебные поддомены вроде login и sso. Список префиксов настраивается отдельно. Исходный URL не изменяется.",
            "Форма показу адреси, якщо значення є URL. «Повна адреса» лишає протокол і шлях; «Лише домен» — назву хоста; «Розумний домен» додатково прибирає службові піддомени на кшталт login і sso. Перелік префіксів налаштовується окремо. Вихідна URL-адреса не змінюється.",
            "Display format when the value is a URL. Full URL retains scheme and path; Domain only shows the host; Smart domain also removes configured service subdomains such as login or sso. Edit that prefix list separately. The original URL is not changed."),
        ["Fit"]=("Как размещать длинное значение, не теряя символов. «Перенос» разбивает на строки; «Уменьшить» сначала пытается вписать в одну строку; «Разделить» пробует две строки возле середины; «Умно» выбирает уменьшение или разделение. Если выбранный способ не подходит, выполняется перенос.",
            "Як розмістити довге значення без втрати символів. «Перенесення» розбиває на рядки; «Зменшити» спочатку намагається вмістити в один рядок; «Розділити» пробує два рядки біля середини; «Розумно» обирає зменшення або розділення. Якщо спосіб не підходить, використовується перенесення.",
            "How to fit long values without losing characters. Wrap makes multiple lines; Shrink first tries a smaller single line; Split tries two lines near the middle; Smart attempts shrinking or splitting. If the chosen strategy cannot fit, the value wraps."),
        ["Weight"]=("Насыщенность шрифта только для значения этого поля. «Как в оформлении» берёт общий вес секретов; 200–800 выбирают отдельное реальное начертание, если оно доступно. Вес влияет на ширину символов и переносы; искусственное утолщение не применяется.",
            "Насиченість шрифту лише для значення цього поля. «Як в оформленні» бере загальну товщину шрифту секретів; 200–800 обирають справжнє накреслення, якщо воно доступне. Вага впливає на ширину символів і перенесення; штучне потовщення не використовується.",
            "Font weight for this field’s value only. Inherit uses the global value weight from Appearance; 200–800 selects an actual available font face. Weight can affect character width and line wrapping; synthetic boldening is not used."),
        ["Size"]=("Размер значения относительно базового размера шрифта из «Оформления». 100% — без изменения; 80% — меньше; 120% — больше. Допустимо 65–160%. Изменение размера влияет на переносы строк, QR-блоки и число карточек.",
            "Розмір значення відносно базового розміру шрифту з «Оформлення». 100% — без змін; 80% — менше; 120% — більше. Діапазон 65–160%. Розмір впливає на перенесення рядків, QR-блоки та кількість карток.",
            "Value size relative to the base font size in Appearance. 100% leaves it unchanged; 80% makes it smaller; 120% larger. Allowed range: 65–160%. Affects wrapping, QR-related blocks and card count."),
        ["Tracking"]=("Дополнительное расстояние между символами значения, в пунктах (pt). Пустое поле наследует общий интервал из «Оформления». Положительное число раздвигает буквы, отрицательное сближает. Допустимо от −0,5 до 1,5 pt; влияет на переносы.",
            "Додаткова відстань між символами значення, у пунктах (pt). Порожнє поле успадковує загальний інтервал з «Оформлення». Додатне число розсуває літери, від’ємне зближує. Діапазон від −0,5 до 1,5 pt; впливає на перенесення.",
            "Extra spacing between value characters, in points (pt). An empty entry inherits the global letter spacing from Appearance. Positive values spread characters apart; negative values bring them closer. Range: −0.5 to 1.5 pt; affects wrapping."),
        ["Group"]=("Группировать ли символы длинного секрета для удобного чтения. «Как в оформлении» наследует общее правило, «Группировать» включает, «Не группировать» отключает, «Авто» пытается определить подходящие случайные значения. Пробелы добавляются только при отображении — оригинал не меняется.",
            "Чи групувати символи довгого секрету для зручного читання. «Як в оформленні» успадковує загальне правило; «Групувати» вмикає; «Не групувати» вимикає; «Авто» намагається визначити відповідні випадкові значення. Пробіли додаються лише для показу — оригінал не змінюється.",
            "Controls grouping characters of long secrets for readability. Inherit uses the global rule; On enables it; Off disables it; Auto attempts to group suitable random-looking values. Separators are display-only and never change the original secret."),
        ["GroupSize"]=("Сколько символов помещать в каждую группу. 0 — использовать общий размер группы из «Оформления»; от 2 до 16 — индивидуальный размер для этого поля. Действует, только если группировка включена и значение достаточно длинное.",
            "Скільки символів має бути в кожній групі. 0 — використовувати загальний розмір з «Оформлення»; від 2 до 16 — окремий розмір для цього поля. Працює лише коли групування увімкнено й значення достатньо довге.",
            "How many characters appear in each group. 0 uses the global group size from Appearance; 2–16 overrides it for this field. Has an effect only when grouping is enabled and the value is sufficiently long."),
        ["Pagination"]=("Авто выбирает правило по содержимому; целиком — строгий перенос поля; разделение допускается только по безопасным границам.","Авто обирає правило за вмістом; цілком — суворе перенесення поля; поділ лише за безпечними межами.","Auto uses the content type; Whole is mandatory; Split uses only safe boundaries."),
        ["Link"]=("Сохранять вместе с выбранным полем ниже. Промежуточные поля входят в блок. Связь ослабляется, если блок больше стороны.","Зберігати разом з вибраним полем нижче. Проміжні поля входять до блоку. Зв’язок послаблюється, якщо блок більший за бік.","Keep with a later field, including intervening fields. Oversized links are relaxed."),
        ["BreakBefore"]=("Начать поле с новой стороны; имеет приоритет над связями.","Почати поле з нового боку; має пріоритет над зв’язками.","Start on a new side; overrides links."),
        ["Alignment"]=("Индивидуальное выравнивание многострочного текста. Последняя строка абзаца не растягивается.",
            "Індивідуальне вирівнювання багаторядкового тексту. Останній рядок абзацу не розтягується.",
            "Override multiline text alignment. The final line of each paragraph is not justified."),
        ["Hyphenation"]=("Индивидуально включить или выключить языковые переносы в этом поле либо использовать настройки оформления. Исходное значение не изменяется.",
            "Окремо увімкнути або вимкнути мовні переноси в цьому полі або використовувати налаштування оформлення. Вихідне значення не змінюється.",
            "Enable or disable word hyphenation for this field, or inherit the template setting. The original value is not modified."),
        ["HyphenLanguage"]=("Язык правил переноса этого поля. Действует при включённых переносах. Дополнительные языки устанавливаются в настройках.",
            "Мова правил переносу цього поля. Діє за увімкнених переносів. Додаткові мови встановлюються в налаштуваннях.",
            "Hyphenation language for this field. Applies when hyphenation is enabled. Install additional languages in Settings."),
        ["GroupSpaces"]=("Расстояние между группами символов. 0 — использовать значение из «Оформления»; от 0,1 до 2,0 — индивидуальный интервал, в долях обычного пробела. Действует только при включённой группировке. Это визуальное разделение, не изменение секрета.",
            "Відстань між групами символів. 0 — використовувати значення з «Оформлення»; від 0,1 до 2,0 — власний інтервал у частках звичайного пробілу. Діє лише за увімкненого групування. Це лише візуальне розділення, не зміна секрету.",
            "Spacing between character groups. 0 inherits the global setting from Appearance; 0.1–2.0 selects a local interval as a fraction of a normal space. Only applies when grouping is enabled. This is visual separation, not a change to the secret."),
    };

